#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# 议题 #58 真账号端到端冒烟向导：登录 → 上传 → 应用 → 清除 → 核对 → 删除
# 生成：/wizard，2026-11-01。用法：bash tools/smoke-cloud-closet.sh
# 产物：当前目录 smoke-issue-58-report.md + .smoke-issue-58.env（可重跑续填）
# 本向导不代你点界面：它逐步告诉你点哪里、收集你看到的状态行，最后打包证据。
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8
ENV_FILE="${ENV_FILE:-.smoke-issue-58.env}"

_unixpath() {
  if command -v cygpath >/dev/null 2>&1; then cygpath -u "$1"; else printf '%s' "$1"; fi
}

banner "议题 #58 皮肤站材质冒烟"

stage "准备：启动器与测试 PNG"
say "这份向导覆盖票面剩下的唯一一步：用真账号跑通登录 → 上传 → 应用 → 清除 → 删除。"
step "启动启动器（仓库根目录，PowerShell）：. .\env.ps1; dotnet run --project src/NebulaLauncher.App/NebulaLauncher.App.csproj"
step "左侧点「皮肤」，找到「云端衣柜」卡片。"
step "准备一张 64×64（或 64×32）的皮肤 PNG，文件名唯一，例如 smoke-58-20261101.png。"
note "可直接复制 src/NebulaLauncher.Core/Resources/Skins/steve.png 再改名。"
note "若上传后提示「已经在衣柜里」，说明这张图站内已有：在画图里改一个像素另存，再重来。"
ask SITE_URL "皮肤站地址（回车用 https://littleskin.cn）："
SITE_URL="${SITE_URL:-https://littleskin.cn}"
ask DATA_DIR "启动器数据目录（回车用 %LocalAppData%\NebulaLauncher）："
if [[ -z "${DATA_DIR:-}" ]]; then
  DATA_DIR="${LOCALAPPDATA:-$HOME/AppData/Local}/NebulaLauncher"
fi
write_env SITE_URL "$SITE_URL"
write_env DATA_DIR "$DATA_DIR"
open_url "$SITE_URL"
pause "启动器已打开、PNG 已准备好后按回车继续"

stage "登录：建立网页会话"
step "在未登录卡里填：站点地址 $SITE_URL、用户名或邮箱、密码，点「登录」。"
note "期望状态行：已登录皮肤站。（本机已有凭据时会先自动登录，显示「已自动登录皮肤站。」）"
note "期望：角色下拉出现你的角色，衣柜列表出现材质。"
if confirm "登录成功、能看到角色和衣柜了吗？"; then
  LOGIN_RESULT="成功"
  LOGIN_ERROR=""
else
  LOGIN_RESULT="失败"
  ask LOGIN_ERROR "把红色错误文本原样贴进来："
fi
write_env LOGIN_RESULT "$LOGIN_RESULT"
if [[ "$LOGIN_RESULT" != "成功" ]]; then
  warn "登录没过，后面的链路无法验证。先解决登录（错误原文已记录），再重跑本向导。"
  finish
  exit 1
fi

stage "上传：本地 PNG → 云端衣柜"
step "确认分类停在「皮肤」。"
step "「细手臂（Alex）」只在 64×32 的 slim 皮肤时勾选；普通 64×64 皮肤保持不勾。"
warn "「公开到皮肤站」默认是勾上的；只想私用测试就取消勾选。"
step "点「上传皮肤」，选你准备的 PNG。"
note "期望状态行：上传成功：<文件名>（tid <数字>）。"
warn "若显示「这张 PNG 已经在衣柜里（tid …），没有重复上传」，删除按钮不会亮；换一张改过像素的 PNG 重来。"
ask UPLOAD_STATUS "把状态行原文贴进来（含 tid）："
ask UPLOAD_TID "只填 tid 数字："
if [[ ! "$UPLOAD_TID" =~ ^[0-9]+$ ]]; then
  warn "tid 不是纯数字，报告里会照原样记录。"
fi
write_env UPLOAD_STATUS "$UPLOAD_STATUS"
write_env UPLOAD_TID "$UPLOAD_TID"

stage "应用：衣柜材质 → 角色"
step "在衣柜列表里选中刚上传的那件（名字应与 PNG 同名）。"
step "在角色下拉里选一个角色；记下名字，冒烟后要把角色恢复原状。"
step "点「应用到角色」。"
note "期望状态行：已应用到角色。"
note "期望角色行变成：<角色名> · 皮肤 #<刚上传的 tid> · 披风 …（或「未设置」）"
ask PLAYER_NAME "角色名："
ask APPLY_STATUS "应用后的状态行原文："
ask PLAYER_LINE_AFTER_APPLY "应用后的角色行原文："
write_env PLAYER_NAME "$PLAYER_NAME"
write_env APPLY_STATUS "$APPLY_STATUS"
write_env PLAYER_LINE_AFTER_APPLY "$PLAYER_LINE_AFTER_APPLY"

stage "清除：角色材质"
step "保持同一个角色，点「清除角色材质」。"
note "期望状态行：已清除角色身上的材质。"
note "期望角色行：皮肤 未设置"
ask CLEAR_STATUS "清除后的状态行原文："
ask PLAYER_LINE_AFTER_CLEAR "清除后的角色行原文："
write_env CLEAR_STATUS "$CLEAR_STATUS"
write_env PLAYER_LINE_AFTER_CLEAR "$PLAYER_LINE_AFTER_CLEAR"

stage "站点侧核对（删除前做）"
say "这一步证明启动器显示的不是假的成功：去 littleskin 网页看同一账号的实际状态。"
open_url "$SITE_URL"
step "进用户中心 → 衣柜：能看到这次上传的材质（名字 = PNG 文件名）。"
step "进角色页：角色材质与启动器刚才的应用/清除结果一致。"
ask CLOSET_SEEN "衣柜里能看到这次上传的材质吗（是/否）："
ask PROFILE_SEEN "角色页材质与启动器一致吗（是/否）："
write_env CLOSET_SEEN "$CLOSET_SEEN"
write_env PROFILE_SEEN "$PROFILE_SEEN"

stage "删除：云端衣柜"
step "回到启动器，重新选中刚上传的那件材质（列表刷新过就用搜索框按文件名搜）。"
step "点「删除云端」——只有启动器自己上传并记录过的材质才可点。"
note "期望状态行：已从云端衣柜删除：<名>"
ask DELETE_STATUS "删除后的状态行原文："
write_env DELETE_STATUS "$DELETE_STATUS"

stage "生成报告"
REPORT="smoke-issue-58-report.md"
LOG_DIR="$(_unixpath "$DATA_DIR")/logs"
LOG_FILE="$LOG_DIR/launcher-$(date +%Y%m%d).log"
{
  printf '# 议题 #58 冒烟记录\n\n'
  printf -- '- 生成时间：%s\n' "$(date '+%Y-%m-%d %H:%M:%S %z')"
  printf -- '- 站点：%s\n' "$SITE_URL"
  printf -- '- 数据目录：%s\n' "$DATA_DIR"
  printf -- '- 日志：%s\n\n' "$LOG_FILE"
  printf '## 逐步结果\n\n'
  printf -- '- 登录：%s\n' "$LOGIN_RESULT"
  printf -- '- 上传：%s\n' "$UPLOAD_STATUS"
  printf -- '- 应用：%s\n' "$APPLY_STATUS"
  printf -- '- 清除：%s\n' "$CLEAR_STATUS"
  printf -- '- 删除：%s\n\n' "$DELETE_STATUS"
  printf -- '- 上传 tid：%s\n' "$UPLOAD_TID"
  printf -- '- 角色：%s\n' "$PLAYER_NAME"
  printf -- '- 应用后角色行：%s\n' "$PLAYER_LINE_AFTER_APPLY"
  printf -- '- 清除后角色行：%s\n\n' "$PLAYER_LINE_AFTER_CLEAR"
  printf -- '- 站点衣柜看到新材质：%s\n' "$CLOSET_SEEN"
  printf -- '- 站点角色页与启动器一致：%s\n\n' "$PROFILE_SEEN"
  if [[ -n "${LOGIN_ERROR:-}" ]]; then
    printf '## 登录错误原文\n\n```text\n%s\n```\n\n' "$LOGIN_ERROR"
  fi
  printf '## 日志摘录\n\n```text\n'
  if [[ -f "$LOG_FILE" ]]; then
    grep -iE '皮肤站|CloudCloset|texture|材质|上传' "$LOG_FILE" | tail -n 60 || printf '(日志里没有匹配行)\n'
  else
    printf '(没有找到日志文件：%s)\n' "$LOG_FILE"
  fi
  printf '```\n'
} > "$REPORT"
say "报告已写到 $REPORT"
step "打开它核对一遍，整段贴进票 #58 的评论；或把路径发给 agent。"
step "可选清理：启动器里点「忘记密码」删掉本机保存的站点凭据；把角色恢复成冒烟前的材质。"
note "重跑本向导会沿用 $ENV_FILE 里已填的值，直接回车即保留。"

finish
